// Met en forme une alerte Alertmanager : embed Discord + rapport archivé.
//
// Aucune investigation ici. Les alertes métriques sont relayées telles
// quelles ; le diagnostic d'objets Kubernetes est le rôle de
// devops-agent, sur son propre workflow.

const hook = $json.body || $json;
const alertes = hook.alerts || [];

// Alertmanager envoie aussi des notifications de résolution : on ne
// veut pas archiver un rapport pour une alerte qui vient de s'éteindre.
const actives = alertes.filter(a => a.status !== 'resolved');
if (actives.length === 0) {
  return [];
}

const premiere = actives[0];
const labels = premiere.labels || {};
const annotations = premiere.annotations || {};

const nom = labels.alertname || 'Alerte inconnue';
const namespace = labels.namespace || '';
const severite = labels.severity || 'info';
const resume = annotations.summary || '';
const description = annotations.description || '';
const debut = premiere.startsAt || '';

// Couleur et icône selon la sévérité Prometheus.
const COULEURS = { critical: 0xe74c3c, warning: 0xf39c12, info: 0x3498db };
const ICONES = { critical: '🔴', warning: '🟠', info: '🔵' };
const couleur = COULEURS[severite] || 0x95a5a6;

const titre = actives.length === 1
  ? `${ICONES[severite] || '⚪'} ${nom}`
  : `${ICONES[severite] || '⚪'} ${nom} (+${actives.length - 1} autres)`;

// Les labels utiles au diagnostic, sans le bruit interne de Prometheus.
const IGNORES = new Set(['alertname', 'severity', 'namespace', 'prometheus',
                         'endpoint', 'job', 'service', 'instance', '__name__']);
const contexte = Object.entries(labels)
  .filter(([k]) => !IGNORES.has(k))
  .map(([k, v]) => `\`${k}\` : ${v}`)
  .join('\n') || '—';

// Quand plusieurs alertes arrivent groupées, les lister toutes.
const listeAlertes = actives
  .map(a => {
    const l = a.labels || {};
    const cible = l.pod || l.deployment || l.node || l.instance || l.job || '';
    return `• ${l.alertname || '?'}${cible ? ` — \`${cible}\`` : ''}`;
  })
  .join('\n');

// ── Chemin d'archivage ───────────────────────────────────────────
// Le conteneur n8n tourne en UTC : on force Europe/Paris.
const local = new Intl.DateTimeFormat('fr-FR', {
  timeZone: 'Europe/Paris',
  year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false
}).formatToParts(new Date()).reduce((a, p) => (a[p.type] = p.value, a), {});
if (local.hour === '24') local.hour = '00';

const horodatage = `${local.year}-${local.month}-${local.day} ${local.hour}:${local.minute}:${local.second}`;
const slug = String(nom).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const dossier = `alertes/${local.year}/${local.month}/${local.day}/` +
                `${local.hour}h${local.minute}m${local.second}s-${slug}`;
const cleMd = `${dossier}/alerte.md`;
const cleHtml = `${dossier}/alerte.html`;

const markdown = [
  `# ${nom}`,
  '',
  `- **Namespace :** ${namespace || '—'}`,
  `- **Sévérité :** ${severite}`,
  `- **Déclenchée à :** ${debut || '—'}`,
  `- **Alertes groupées :** ${actives.length}`,
  '',
  '## Description',
  '',
  resume || description || '_(pas de description)_',
  ...(description && description !== resume ? ['', description] : []),
  '',
  '## Contexte',
  '',
  contexte,
  ...(actives.length > 1 ? ['', '## Alertes du groupe', '', listeAlertes] : []),
  '',
  '---',
  `_Alerte Prometheus relayée le ${horodatage} (Europe/Paris)_`,
  '',
  '_Les diagnostics d\'objets Kubernetes sont produits séparément par devops-agent._'
].join('\n');

// ── Rapport HTML ─────────────────────────────────────────────────
const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const teinte = { critical: '#e74c3c', warning: '#f39c12', info: '#3498db' }[severite] || '#95a5a6';

const rendre = (md) => esc(md)
  .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
  .replace(/`([^`]+)`/g, '<code>$1</code>')
  .split('\n')
  .map(l => /^[-•] /.test(l) ? `<li>${l.slice(2)}</li>` : l)
  .join('\n')
  .replace(/(?:<li>.*<\/li>\n?)+/g, m => `<ul>${m.replace(/\n/g, '')}</ul>`)
  .replace(/\n/g, '<br>')
  .replace(/<br>(<ul>|<\/ul>)/g, '$1');

const html = `<!doctype html>
<html lang="fr"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(nom)}</title>
<style>
  :root { color-scheme: light dark; }
  body { margin:0; padding:2rem 1rem; background:#f6f7f9; color:#1a1d21;
         font:15px/1.65 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif; }
  .wrap { max-width:820px; margin:0 auto; background:#fff; border-radius:10px;
          box-shadow:0 1px 3px rgba(0,0,0,.12); overflow:hidden; }
  header { border-left:5px solid ${teinte}; padding:1.25rem 1.5rem; background:#fafbfc; }
  h1 { margin:0 0 .5rem; font-size:1.35rem; }
  .meta { display:flex; flex-wrap:wrap; gap:.4rem 1.25rem; font-size:.85rem; color:#5b6470; }
  .meta b { color:#1a1d21; font-weight:600; }
  .badge { display:inline-block; padding:.1rem .5rem; border-radius:99px;
           background:${teinte}; color:#fff; font-size:.75rem; font-weight:600; }
  main { padding:1.25rem 1.5rem 2rem; }
  h2 { font-size:1.05rem; margin:1.75rem 0 .5rem; padding-bottom:.3rem;
       border-bottom:1px solid #e6e8eb; }
  h2:first-child { margin-top:0; }
  code { background:#eef0f3; padding:.12em .38em; border-radius:4px;
         font:.88em ui-monospace,SFMono-Regular,Menlo,monospace; }
  ul { margin:.4rem 0; padding-left:1.3rem; }
  footer { padding:1rem 1.5rem; border-top:1px solid #e6e8eb; color:#8b939e; font-size:.8rem; }
  @media (prefers-color-scheme: dark) {
    body { background:#15181c; color:#e6e8eb; }
    .wrap { background:#1e2229; box-shadow:none; }
    header { background:#22262e; }
    .meta b, h1 { color:#e6e8eb; }
    h2 { border-color:#333a44; }
    code { background:#2b313a; }
    footer { border-color:#333a44; }
  }
</style></head><body><div class="wrap">
<header>
  <h1>${esc(nom)}</h1>
  <div class="meta">
    <span><b>Namespace</b> ${esc(namespace) || '—'}</span>
    <span><b>Sévérité</b> <span class="badge">${esc(severite)}</span></span>
    <span><b>Déclenchée à</b> ${esc(debut) || '—'}</span>
  </div>
</header>
<main>
  <h2>Description</h2>
  <p>${esc(resume || description || '(pas de description)')}</p>
  ${description && description !== resume ? `<p>${esc(description)}</p>` : ''}
  <h2>Contexte</h2>
  ${rendre(contexte)}
  ${actives.length > 1 ? '<h2>Alertes du groupe</h2>' + rendre(listeAlertes) : ''}
</main>
<footer>Alerte Prometheus relayée le ${horodatage} (Europe/Paris) — <code>${esc(cleMd)}</code></footer>
</div></body></html>`;

const baseRapports = 'https://reports.cluster.afflair.app';
const encoder = (k) => k.split('/').map(encodeURIComponent).join('/');

const embed = {
  title: titre,
  description: (resume || description || '_(pas de description)_').slice(0, 400),
  color: couleur,
  fields: [
    { name: 'Namespace', value: namespace || '—', inline: true },
    { name: 'Sévérité', value: severite, inline: true },
    { name: 'Déclenchée à', value: debut ? debut.slice(0, 19).replace('T', ' ') : '—', inline: true },
    { name: 'Contexte', value: contexte.slice(0, 1024) },
    ...(actives.length > 1
        ? [{ name: `Alertes groupées (${actives.length})`, value: listeAlertes.slice(0, 1024) }]
        : [])
  ],
  timestamp: new Date().toISOString()
};

return [{
  json: {
    embed, cleMd, cleHtml,
    urlRapport: `${baseRapports}/${encoder(cleHtml)}`
  },
  binary: {
    data: {
      data: Buffer.from(markdown, 'utf-8').toString('base64'),
      mimeType: 'text/markdown', fileName: 'alerte.md'
    },
    html: {
      data: Buffer.from(html, 'utf-8').toString('base64'),
      mimeType: 'text/html', fileName: 'alerte.html'
    }
  }
}];
